import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { tablesApi, ordersApi } from '../utils/api';
import toast from 'react-hot-toast';
import OrderModal from './OrderModal';
import BillModal from './BillModal';

const STATE_COLORS = {
  free: 'bg-emerald-900 border-emerald-500 text-emerald-300',
  reserved: 'bg-blue-900 border-blue-500 text-blue-300',
  occupied: 'bg-amber-900 border-amber-500 text-amber-300',
  awaiting_bill: 'bg-purple-900 border-purple-500 text-purple-300',
  cleared: 'bg-gray-800 border-gray-600 text-gray-400',
};

const STATE_LABELS = {
  free: 'FREE',
  reserved: 'RESERVED',
  occupied: 'OCCUPIED',
  awaiting_bill: 'AWAITING BILL',
  cleared: 'CLEARED',
};

export default function TablesView() {
  const { tables, staff, refreshTables, refreshKitchen } = useApp();
  const [seatModal, setSeatModal] = useState(null);
  const [orderModal, setOrderModal] = useState(null);
  const [billModal, setBillModal] = useState(null);
  const [customerName, setCustomerName] = useState('');
  const [seatStaff, setSeatStaff] = useState('');

  const waiters = staff.filter((s) => ['waiter', 'manager'].includes(s.role));

  async function handleSeat(table) {
    if (!customerName.trim()) { toast.error('Enter customer name'); return; }
    if (!seatStaff) { toast.error('Select a staff member'); return; }
    try {
      await tablesApi.seat(table.id, customerName.trim());
      await refreshTables();
      setSeatModal(null);
      setCustomerName('');
      setSeatStaff('');
      toast.success(`Table ${table.id} seated`);
    } catch (err) {
      toast.error(err.response?.data?.error || 'Failed to seat table');
    }
  }

  async function handleClear(tableId) {
    try {
      await tablesApi.clear(tableId);
      await refreshTables();
      toast.success(`Table ${tableId} cleared`);
    } catch {
      toast.error('Failed to clear table');
    }
  }

  return (
    <div>
      <h2 className="text-2xl font-bold text-white mb-6">Table Management</h2>
      <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
        {tables.map((table) => (
          <div
            key={table.id}
            className={`rounded-xl border-2 p-5 ${STATE_COLORS[table.state] || STATE_COLORS.free}`}
          >
            <div className="flex justify-between items-start mb-3">
              <span className="text-2xl font-bold">Table {table.id}</span>
              <span className="text-xs font-semibold px-2 py-1 rounded-full bg-black/30">
                {STATE_LABELS[table.state]}
              </span>
            </div>
            <p className="text-sm mb-1">Capacity: {table.capacity} guests</p>
            {table.customerName && <p className="text-sm mb-3">Guest: {table.customerName}</p>}

            <div className="flex flex-wrap gap-2 mt-3">
              {table.state === 'free' && (
                <button
                  onClick={() => setSeatModal(table)}
                  className="btn-sm bg-emerald-600 hover:bg-emerald-500 text-white"
                >
                  Seat Customer
                </button>
              )}
              {table.state === 'occupied' && (
                <>
                  <button
                    onClick={() => setOrderModal(table)}
                    className="btn-sm bg-amber-600 hover:bg-amber-500 text-white"
                  >
                    Place Order
                  </button>
                  <button
                    onClick={() => setBillModal(table)}
                    className="btn-sm bg-purple-600 hover:bg-purple-500 text-white"
                  >
                    Generate Bill
                  </button>
                </>
              )}
              {['occupied', 'awaiting_bill', 'cleared'].includes(table.state) && (
                <button
                  onClick={() => handleClear(table.id)}
                  className="btn-sm bg-gray-600 hover:bg-gray-500 text-white"
                >
                  Clear Table
                </button>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* Seat Modal */}
      {seatModal && (
        <div className="modal-backdrop" onClick={() => setSeatModal(null)}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <h3 className="text-xl font-bold text-white mb-4">Seat Customer — Table {seatModal.id}</h3>
            <input
              className="input w-full mb-3"
              placeholder="Customer name"
              value={customerName}
              onChange={(e) => setCustomerName(e.target.value)}
              maxLength={80}
            />
            <select
              className="input w-full mb-4"
              value={seatStaff}
              onChange={(e) => setSeatStaff(e.target.value)}
            >
              <option value="">Select staff member</option>
              {waiters.map((s) => (
                <option key={s.id} value={s.id}>{s.name} ({s.role})</option>
              ))}
            </select>
            <div className="flex gap-3">
              <button onClick={() => handleSeat(seatModal)} className="btn bg-emerald-600 hover:bg-emerald-500 text-white flex-1">
                Confirm Seating
              </button>
              <button onClick={() => setSeatModal(null)} className="btn bg-gray-700 hover:bg-gray-600 text-white flex-1">
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}

      {orderModal && (
        <OrderModal
          table={orderModal}
          staffId={seatStaff || waiters[0]?.id}
          onClose={() => { setOrderModal(null); refreshTables(); refreshKitchen(); }}
        />
      )}

      {billModal && (
        <BillModal
          table={billModal}
          onClose={() => { setBillModal(null); refreshTables(); }}
        />
      )}
    </div>
  );
}
